284	export async function buildMatch08(): Promise<Match08> {
285	  const L: Layout = await fetch(new URL('../../assets/textures/match08/proj08.json', import.meta.url).href).then((r) => r.json());
286	  const plate = await new THREE.TextureLoader().loadAsync(new URL('../../assets/textures/match08/plate08_hybrid.png', import.meta.url).href);
287	  plate.colorSpace = THREE.NoColorSpace; // raw display values: the shader inverts the post chain itself
288	  plate.minFilter = THREE.LinearMipmapLinearFilter;
289	  plate.anisotropy = 8;
290	
291	  // the projector = the locked game camera the picture was matched to
292	  const [W, H] = L.camera.size;
293	  const proj = new THREE.PerspectiveCamera(L.camera.fov, W / H, 0.2, 160);
294	  proj.matrixWorld.fromArray(L.camera.matrixWorld);
295	  proj.matrixWorld.decompose(proj.position, proj.quaternion, proj.scale);
296	  proj.matrixWorldInverse.copy(proj.matrixWorld).invert();
297	  proj.updateProjectionMatrix();
298	  const projVP = new THREE.Matrix4().multiplyMatrices(proj.projectionMatrix, proj.matrixWorldInverse);
299	
300	  const depthRT = new THREE.WebGLRenderTarget(1024, Math.round((1024 * H) / W), { depthBuffer: true });
301	  depthRT.depthTexture = new THREE.DepthTexture(depthRT.width, depthRT.height, THREE.UnsignedIntType);
302	  const shared = {
303	    uPlate: { value: plate },
304	    uDepth: { value: depthRT.depthTexture as THREE.Texture },
305	    uUseDepth: { value: 0 },
306	    uNearFar: { value: new THREE.Vector2(proj.near, proj.far) },
307	    uProjVP: { value: projVP },
